package com.alex.mycelialmind.registry;

import com.alex.mycelialmind.MycelialMind;
import net.minecraft.advancements.AdvancementHolder;
import net.minecraft.resources.ResourceLocation;
import net.minecraft.server.MinecraftServer;
import net.minecraft.server.level.ServerPlayer;
import org.jetbrains.annotations.Nullable;

/**
 * Typed handles and safe runtime award helper for code-triggered progression advancements
 * generated by {@code MycelialAdvancementProvider}.
 */
public final class ModAdvancements {
    public static final TriggeredAdvancement BASTION_TIER3 =
            triggered("bastion_tier3", "upgrade_tier3");
    public static final TriggeredAdvancement SOVEREIGN_COLONY_TIER3 =
            triggered("sovereign_colony_tier3", "upgrade_tier3");
    public static final TriggeredAdvancement PURIFIER_DRONE_DEPLOYED =
            triggered("purifier_drone_deployed", "deploy_drone");
    public static final TriggeredAdvancement IMMUNE_HOMEOSTASIS =
            triggered("immune_homeostasis", "overcome_immune_response");
    public static final TriggeredAdvancement RECOVERED_GARDEN =
            triggered("recovered_garden", "recover_garden");
    public static final TriggeredAdvancement RECOVERED_ROUTE =
            triggered("recovered_route", "recover_route");

    private ModAdvancements() {
    }

    public static boolean award(@Nullable ServerPlayer player, TriggeredAdvancement advancement) {
        if (player == null) {
            return false;
        }
        MinecraftServer server = player.getServer();
        if (server == null) {
            return false;
        }
        ModCriteriaTriggers.HIVE_MILESTONE.get().trigger(player, advancement.id().getPath());
        AdvancementHolder holder = server.getAdvancements().get(advancement.id());
        if (holder == null) {
            return false;
        }
        if (player.getAdvancements().getOrStartProgress(holder).isDone()) {
            return true;
        }
        return player.getAdvancements().award(holder, advancement.criterion());
    }

    private static TriggeredAdvancement triggered(String path, String criterion) {
        return new TriggeredAdvancement(
                ResourceLocation.fromNamespaceAndPath(MycelialMind.MODID, path),
                criterion
        );
    }

    public record TriggeredAdvancement(ResourceLocation id, String criterion) {
    }
}
